class EmbeddingModelRegistry:
    def __init__(self):
        self.models = {}

    def add_model(self, name: str, dims: int, retrieval_score: float,
                  speed_score: float, params: int):
        self.models[name] = {
            "name": name,
            "dims": dims,
            "retrieval_score": retrieval_score,
            "speed_score": speed_score,
            "params": params,
        }

    @staticmethod
    def _summary(m):
        return {"name": m["name"], "retrieval_score": m["retrieval_score"], "dims": m["dims"]}

    def best_for_retrieval(self, top_k: int = 3) -> list[dict]:
        ranked = sorted(self.models.values(), key=lambda m: m["retrieval_score"], reverse=True)
        return [self._summary(m) for m in ranked[:top_k]]

    def best_under_params(self, max_params: int,
                          top_k: int = 3) -> list[dict]:
        eligible = [m for m in self.models.values() if m["params"] <= max_params]
        ranked = sorted(eligible, key=lambda m: m["retrieval_score"], reverse=True)
        return [self._summary(m) for m in ranked[:top_k]]

    def compare(self, model_a: str, model_b: str) -> dict:
        a = self.models[model_a]
        b = self.models[model_b]
        return {
            "retrieval": model_a if a["retrieval_score"] >= b["retrieval_score"] else model_b,
            "speed": model_a if a["speed_score"] >= b["speed_score"] else model_b,
            "efficiency": model_a if a["params"] <= b["params"] else model_b,
        }


# Test it:
reg = EmbeddingModelRegistry()
reg.add_model("bge-large", 1024, 63.6, 5.0, 335_000_000)
reg.add_model("bge-small", 384, 59.2, 8.5, 33_000_000)
reg.add_model("MiniLM", 384, 49.5, 9.8, 22_000_000)
reg.add_model("NV-Embed-v2", 4096, 72.3, 2.1, 7_800_000_000)

top = reg.best_for_retrieval(top_k=2)
print(top[0]["name"])
print(top[1]["name"])

small = reg.best_under_params(max_params=100_000_000, top_k=2)
print(small[0]["name"])

cmp = reg.compare("bge-small", "MiniLM")
print(cmp["retrieval"])
print(cmp["speed"])
print(cmp["efficiency"])
